fn main() -> Void {
    let grid: Text[] = ["..#...", "....#.", ".#....", "...#..", ".#...#", "....#."];
    let rows: Int = 6;
    let cols: Int = 6;

    let visited: Bool[][] = [];
    loop r in 0..rows {
        let row: Bool[] = [];
        loop c in 0..cols {
            row = row + [false];
        }
        visited = visited + [row];
    }

    let totalFloor: Int = 0;
    loop r in 0..rows {
        loop c in 0..cols {
            if grid[r][c] == "." {
                totalFloor = totalFloor + 1;
            }
        }
    }

    let r: Int = 0;
    let c: Int = 0;
    let dir: Int = 1;
    let cleanedCount: Int = 0;
    let lastRow: Int = 0;

    if grid[0][0] == "." {
        visited[0][0] = true;
        cleanedCount = 1;
        lastRow = 0;
    }

    loop {
        let nextC: Int = c + dir;
        let canMove: Bool = false;
        if nextC >= 0 && nextC < cols && grid[r][nextC] == "." {
            canMove = true;
        }
        if canMove {
            c = nextC;
            if !visited[r][c] {
                visited[r][c] = true;
                cleanedCount = cleanedCount + 1;
                lastRow = r;
            }
        } else {
            let nextR: Int = r + 1;
            if nextR < rows && grid[nextR][c] == "." {
                r = nextR;
                dir = -dir;
                if !visited[r][c] {
                    visited[r][c] = true;
                    cleanedCount = cleanedCount + 1;
                    lastRow = r;
                }
            } else {
                break;
            }
        }
    }

    let coverage: Real = cleanedCount * 100.0 / totalFloor;
    let coverageRounded: Real = round_to(coverage, 2);

    fx {
        println("CleanedCount: ", cleanedCount);
        println("TotalFloor: ", totalFloor);
        println("Coverage: ", format_float(coverageRounded, 2));
        println("LastRow: ", lastRow);
    }
    ret;
}

