fn classifySize(code: Text) -> Text {
    if code == "S" {
        ret "TINY";
    }
    if code == "M" {
        ret "MEDIUM";
    }
    if code == "L" {
        ret "BIG";
    }
    if code == "XL" {
        ret "HUGE";
    }
    ret "UNKNOWN";
}

