fn main() -> Void {
    let tags: Text[] = ["101=12=Green", "102=8=Blue", "103=15=Green", "104=6=Red", "105=10=Blue", "106=9=Green"];
    let owners: Text[] = [];
    let counts: Map[Text, Int] = {};
    let totals: Map[Text, Int] = {};
    let grandTotal: Int = 0;

    loop tag in tags {
        let parts: Text[] = split(tag, "=");
        let size: Int = parse_int(parts[1]);
        let owner: Text = parts[2];
        if !has(counts, owner) {
            owners = owners + [owner];
            counts[owner] = 0;
            totals[owner] = 0;
        }
        counts[owner] = counts[owner] + 1;
        totals[owner] = totals[owner] + size;
        grandTotal = grandTotal + size;
    }

    let sortedOwners: Text[] = sorted(owners);

    loop owner in sortedOwners {
        fx {
            println(owner, " plots ", counts[owner], " total ", totals[owner]);
        }
    }

    let avg: Real = grandTotal * 1.0 / length(tags);
    fx {
        println("average plot size ", format_float(avg, 1));
    }

    ret;
}

