fn main() -> Void {
    let entries: Text[] = ["12=Central=3", "12=Central=17", "45=Airport=9", "7=Harbor=1", "45=Airport=22"];

    type RouteBest {
        route: Int = 0;
        dest: Text = "";
        minutes: Int = 0;
    }

    let bests: RouteBest[] = [];

    loop entry in entries {
        let parts: Text[] = split(entry, "=");
        let r: Int = parse_int(parts[0]);
        let d: Text = parts[1];
        let m: Int = parse_int(parts[2]);

        let found: Bool = false;
        loop i in 0..length(bests) {
            if bests[i].route == r {
                found = true;
                if m < bests[i].minutes {
                    bests[i].minutes = m;
                    bests[i].dest = d;
                }
            }
        }
        if !found {
            bests = bests + [new RouteBest { route: r, dest: d, minutes: m }];
        }
    }

    // sort ascending by route
    loop i in 0..length(bests) {
        loop j in i + 1..length(bests) {
            if bests[j].route < bests[i].route {
                let tmp: RouteBest = bests[i];
                bests[i] = bests[j];
                bests[j] = tmp;
            }
        }
    }

    let overallRoute: Int = bests[0].route;
    let overallMin: Int = bests[0].minutes;

    fx {
        loop i in 0..length(bests) {
            println("Route ", bests[i].route, " to ", bests[i].dest, " arrives in ", bests[i].minutes, " min");
            if bests[i].minutes < overallMin {
                overallMin = bests[i].minutes;
                overallRoute = bests[i].route;
            }
        }
        println("next bus route ", overallRoute, " in ", overallMin, " min");
    }

    ret;
}

type Player {
    name: Text = "";
    clock: Int = 0;
    lost: Bool = false;
}

type Board {
    white: Int = 0;
    black: Int = 0;
}

fn main() -> Void {
    let names: Text[] = ["Alice", "Bob", "Carol", "Dave", "Eve", "Frank", "Grace", "Henry"];
    let clocks: Int[] = [90, 75, 60, 100, 45, 50, 120, 40];
    let lost: Bool[] = [false, false, false, false, false, false, false, false];
    let boards: Board[] = [
        new Board { white: 0, black: 1 },
        new Board { white: 2, black: 3 },
        new Board { white: 4, black: 5 },
        new Board { white: 6, black: 7 }
    ];
    let rounds: Int[] = [30, 45, 60];

    loop r in 0..3 {
        let len: Int = rounds[r];
        let losers: Text[] = [];
        loop b in 0..4 {
            let w: Int = boards[b].white;
            let k: Int = boards[b].black;
            let wOut: Bool = false;
            let kOut: Bool = false;
            if !lost[w] {
                if clocks[w] < len {
                    clocks[w] = 0;
                    lost[w] = true;
                    wOut = true;
                } else {
                    clocks[w] = clocks[w] - len;
                }
            }
            if !lost[k] {
                if clocks[k] < len {
                    clocks[k] = 0;
                    lost[k] = true;
                    kOut = true;
                } else {
                    clocks[k] = clocks[k] - len;
                }
            }
            if wOut {
                losers = losers + [names[w]];
            }
            if kOut {
                losers = losers + [names[k]];
            }
        }
        let line: Text;
        if length(losers) == 0 {
            line = "none";
        } else {
            line = join(losers, ",");
        }
        fx {
            println("R", r + 1, " ", line);
        }
    }

    fx {
        loop i in 0..8 {
            println(names[i], " ", clocks[i]);
        }
    }
    ret;
}

fn main() -> Void {
    let names: Text[] = ["Towels", "Shirts", "Jeans", "Socks", "Sheets", "Uniforms"];
    let arrivals: Int[] = [0, 5, 8, 15, 20, 25];
    let durations: Int[] = [30, 25, 40, 20, 35, 25];
    let machineFree: Int[] = [0, 0, 0];
    let machineFirstStart: Int[] = [-1, -1, -1];
    let machineLoadSum: Int[] = [0, 0, 0];
    let globalEnd: Int = 0;

    loop i in 0..6 {
        let m: Int = i % 3;
        let start: Int = max(arrivals[i], machineFree[m]);
        let end: Int = start + durations[i];
        machineFree[m] = end;
        if machineFirstStart[m] == -1 {
            machineFirstStart[m] = start;
        }
        machineLoadSum[m] = machineLoadSum[m] + durations[i];
        if end > globalEnd {
            globalEnd = end;
        }
        fx {
            println(names[i], " M", m + 1, " ", start, " ", end);
        }
    }

    loop m in 0..3 {
        let idle: Int = globalEnd - machineFirstStart[m] - machineLoadSum[m];
        fx {
            println("M", m + 1, " ", idle);
        }
    }

    ret;
}

fn main() -> Void {
    let colors: Text[] = ["Red", "Pink", "White", "Red"];
    let n: Int = length(colors);
    let seen: Map[Text, Bool] = {};
    let count: Int = 0;

    loop a in 0..n {
        loop b in 0..n {
            if b == a {
                continue;
            }
            loop c in 0..n {
                if c == a or c == b {
                    continue;
                }
                loop d in 0..n {
                    if d == a or d == b or d == c {
                        continue;
                    }
                    let line: Text = colors[a] + " " + colors[b] + " " + colors[c] + " " + colors[d];
                    if !has(seen, line) {
                        seen[line] = true;
                        count = count + 1;
                    }
                }
            }
        }
    }

    let lines: Text[] = [];
    loop key in seen {
        lines = lines + [key];
    }
    let sorted: Text[] = sorted(lines);

    fx {
        loop line in sorted {
            println(line);
        }
        println("Distinct arrangements: ", count);
    }
    ret;
}

