fn main() -> Void {
    let F: Int[][] = [
        [0, 3, 0, 5, 0],
        [3, 0, 4, 0, 7],
        [0, 4, 0, 6, 0],
        [5, 0, 6, 0, 8],
        [0, 7, 0, 8, 0]
    ];

    let n: Int = 5;
    let src: Int = 0;
    let dst: Int = 4;

    let direct: Int = F[src][dst];
    let cheapest: Int = 999999;
    let bestTransfer: Int = -1;

    if direct > 0 {
        cheapest = direct;
    }

    loop k in 1..n - 1 {
        let a: Int = F[src][k];
        let b: Int = F[k][dst];
        if a > 0 && b > 0 {
            let cost: Int = a + b;
            if cost < cheapest {
                cheapest = cost;
                bestTransfer = k;
            }
        }
    }

    let directCount: Int = 0;
    let maxDirect: Int = 0;
    loop i in 0..n {
        loop j in 0..n {
            if i != j {
                let v: Int = F[i][j];
                if v > 0 {
                    directCount = directCount + 1;
                    if v > maxDirect {
                        maxDirect = v;
                    }
                }
            }
        }
    }

    let transferLabel: Text = if bestTransfer == -1 { "NONE" } else { int_to_text(bestTransfer) };

    fx {
        println("Cheapest: ", cheapest);
        println("DirectCount: ", directCount);
        println("BestTransfer: ", transferLabel);
        println("MaxDirect: ", maxDirect);
    }
    ret;
}

fn main() -> Void {
