fn main() -> Void {
    let Q: Int[][] = [
        [7, 8, 6, 9],
        [9, 6, 8, 5],
        [6, 9, 7, 8],
        [8, 7, 9, 7],
        [5, 8, 5, 10]
    ];
    let weights: Int[] = [3, 2, 4, 1];
    let rows: Int = length(Q);
    let cols: Int = length(weights);

    let scores: Int[] = [];
    loop p in 0..rows {
        let s: Int = 0;
        loop c in 0..cols {
            s = s + Q[p][c] * weights[c];
        }
        scores = scores + [s];
    }

    let topPaper: Int = 0;
    let bestScore: Int = scores[0];
    loop p in 1..rows {
        if scores[p] > bestScore {
            bestScore = scores[p];
            topPaper = p;
        }
    }

    let topCriterion: Int = 0;
    let bestAvg: Real = 0.0;
    loop c in 0..cols {
        let total: Int = 0;
        loop p in 0..rows {
            total = total + Q[p][c];
        }
        let avg: Real = total * 1.0 / rows;
        if c == 0 || avg > bestAvg {
            bestAvg = avg;
            topCriterion = c;
        }
    }

    let over70: Int = 0;
    loop p in 0..rows {
        if scores[p] > 70 {
            over70 = over70 + 1;
        }
    }

    fx {
        println("TopPaper: ", topPaper);
        println("TopCriterion: ", topCriterion);
        println("Over70: ", over70);
        println("BestScore: ", bestScore);
    }
    ret;
}

fn main() -> Void {
