type Student {
    name: Text = "";
    grade: Int = 0;
}

fn main() -> Void {
    let students: Student[] = [
        new Student { name: "Tom", grade: 88 },
        new Student { name: "Susan", grade: 95 },
        new Student { name: "Kevin", grade: 72 },
        new Student { name: "Laura", grade: 88 },
        new Student { name: "Derek", grade: 95 }
    ];

    // Sort by grade descending, then name ascending
    let n: Int = length(students);
    loop i in 0..n {
        loop j in 0..(n - 1 - i) {
            let swap: Bool = false;
            if students[j].grade < students[j + 1].grade {
                swap = true;
            }
            if students[j].grade == students[j + 1].grade && students[j].name > students[j + 1].name {
                swap = true;
            }
            if swap {
                let tmp: Student = students[j];
                students[j] = students[j + 1];
                students[j + 1] = tmp;
            }
        }
    }

    // Assign ranks
    let ranks: Int[] = [];
    loop i in 0..n {
        if i > 0 && students[i].grade == students[i - 1].grade {
            ranks = ranks + [ranks[i - 1]];
        } else {
            ranks = ranks + [i + 1];
        }
    }

    fx {
        loop i in 0..n {
            println(ranks[i], " ", students[i].name, ": ", students[i].grade);
        }
    }
    ret;
}
